"""Publish the maintained mission/wave reference from the actual campaign data."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parent.parent
cfg=json.loads((ROOT/'tools/campaign-config.json').read_text(encoding='utf-8'))
lines=['# Galactic Campaign — Level & Wave Reference','','Source of truth: `tools/campaign-config.json`. Register edits with `python tools/build-campaign.py`, then `python tools/embed-free-placement.py`. No tower statistics or recipes are changed by the campaign.','','Gold is per run. Kill income below includes the boss reward and its conditional reinforcement group; it is an upper bound if the boss dies before that group is triggered. Wave-completion gifts remain0. No tutorial adds free Gold.','','| Mission | Name | Start Gold | Lives | Waves | Potential kill Gold | Boss |','| --- | --- | ---: | ---: | ---: | ---: | --- |']
for l in cfg['Levels']:lines.append(f"| {l['Id']} | {l['Name']} | {l['StartingGold']} | {l['StartingLives']} | {len(l['Waves'])} | {l['ExpectedKillGold']} | {'Yes' if l['Boss'] else '-'} |")
preparation=['Opening:2Star Cannons cost600; the guided run places one, then demonstrates an existing160Gold upgrade.','Establish several firing positions, then use damage or speed upgrades against mixed groups.','Use cross-lane coverage and Nova splash against armor/support formations.','Prepare a developed tower network and consider higher upgrades before the boss wave.','Build a broad defense and use late upgrades/Fusion when the run economy supports them.']
for chapter in cfg['Chapters']:
    b=chapter['Boss'];lines+=['',f"## Chapter {chapter['Id']} — {chapter['Name']}",'',chapter['Description'],'',preparation[chapter['Id']-1],'',f"Boss: **{b['Name']}**. HP{b['HP']}, armor{b['Armor']}, speed{b['Speed']}, kill reward{b['Reward']}. Cast start-to-start cooldown{b['CastCooldown']}s; the native0.8s stationary cast/release at0.6s and Fortification armor buff are reused.",'',b['Pattern'], '',f"Temporary percent defense: {b['ShieldPercent']}% for{b['ShieldSeconds']}s after release. Surge: ×{b['SurgeMultiplier']} for{b['SurgeSeconds']}s. One half-health reinforcement group: {', '.join(b['Reserves']) or 'none'}. The boss must be killed before reaching Finish."]
    for l in [v for v in cfg['Levels'] if v['Chapter']==chapter['Id']]:
        lines+=['',f"### {l['Id']} — {l['Name']}",'',f"Starting Gold{l['StartingGold']}; Lives{l['StartingLives']}; intermission{l['Intermission']}s in Auto mode; {len(l['Waves'])}waves. Victory requires every configured wave cleared with Lives>0, plus the boss killed on boss missions.",'','| Wave | Regular enemies (type × count) | Interval s | HP × | Speed × | Potential kill Gold | Boss |','| ---: | --- | ---: | ---: | ---: | ---: | --- |']
        for w in l['Waves']:
            comp=', '.join(f'{k} ×{v}' for k,v in w['Enemies'].items());lines.append(f"| {w['Number']} | {comp} | {w['SpawnInterval']} | {w['HealthScale']} | {w['SpeedScale']} | {w['ExpectedGold']} | {b['Name'] if w['Boss'] else '-'} |")
lines+=['','## Manual playtesting checklist','','- Use a fresh isolated profile to exercise both introductions without clearing a player’s existing saves.','- Play missions1-1 and1-2 using both first-time and Skip flows; compare one upgraded opening tower against two unupgraded openings.','- Play every mission without fixture damage; record failed placements, escapes, remaining Lives, total spending, completion time and chosen upgrades.','- Test both upgrade paths,5-2/2-5 locking and Pure Fusion on later missions.','- Recheck armor/splash interaction and all boss ability telegraphs with a sparse defense and a developed defense.','- Test manual/auto,1×/2×, Tactical Fusion0.5×, Index opening, audio settings and desktop minimize/restore.','- Defeat, Restart, Return to Levels and replay a completed mission; verify no extra unlocks or erased progress.','- Reload the application and confirm completion/tutorial flags, original audio preferences and Fusion discoveries remain.','','Automated integration tests cover all25mission contracts; they are not a human win-rate study. Full natural-combat coverage and boss-wave benchmark results are reported in `CAMPAIGN_REPORT.md`.']
(ROOT/'CAMPAIGN_LEVEL_REFERENCE.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')
print('Published25mission summaries and',sum(len(l['Waves']) for l in cfg['Levels']),'explicit wave rows. No project copy created.')
